correctedCode:
public class DoubleValue {
    public static void main(String[] args) {
        String input = "twenty";
        try {
            int value = Integer.parseInt(input);
            System.out.println(value * 2);
        } catch (NumberFormatException e) {
            System.out.println("Invalid number: " + input);
        }
    }
}
